L109:                 bypass_hook_trust: false,
L110:                 hook_states: &hook_states,
L111:                 env: HashMap::new(),
L112:                 plugin_id: None,
L113:             };
L114:             if !policy.allows(&policy_source) {
L115:                 continue;
L116:             }
L117:             let json_hooks = match layer.hooks_config_folder() {
L118:                 Some(config_folder) if visited_json_hook_folders.insert(config_folder.clone()) => {
L119:                     load_hooks_json(Some(config_folder.as_path()), &mut warnings)
L120:                 }
L121:                 _ => None,
L122:             };
L123:             let toml_hooks = load_toml_hooks_from_layer(layer, &mut warnings);
L124:             if let (Some((json_source_path, json_events)), Some((toml_source_path, toml_events))) =
L125:                 (&json_hooks, &toml_hooks)
L126:                 && !json_events.is_empty()
L127:                 && !toml_events.is_empty()
L128:             {
L129:                 warnings.push(format!(
L130:                     "loading hooks from both {} and {}; prefer a single representation for this layer",
L131:                     json_source_path.display(),
L132:                     toml_source_path.display()
L133:                 ));
L134:             }
L135:             for (source_path, hook_events) in [json_hooks, toml_hooks].into_iter().flatten() {
L136:                 append_hook_events(
L137:                     &mut handlers,
L138:                     &mut hook_entries,
L139:                     &mut warnings,
L140:                     &mut display_order,
L141:                     HookHandlerSource {
L142:                         path: &source_path,
L143:                         key_source: source_path.display().to_string(),
L144:                         source: hook_source,
L145:                         is_managed,
L146:                         bypass_hook_trust: policy.bypass_hook_trust,
L147:                         hook_states: &hook_states,
L148:                         env: HashMap::new(),
L149:                         plugin_id: None,
L150:                     },
L151:                     hook_events,
L152:                     policy,
L153:                 );
L154:             }
L155:         }
L156:     }
L157:     append_plugin_hook_sources(
L158:         &mut handlers,
L159:         &mut hook_entries,
L160:         &mut warnings,
L161:         &mut display_order,
L162:         plugin_hook_sources,
L163:         &hook_states,
L164:         policy,
L165:     );
L166: 
L167:     DiscoveryResult {
L168:         handlers,
L169:         hook_entries,
L170:         warnings,
L171:     }
L172: }
