L256: fn managed_hooks_source_path(
L257:     managed_hooks: &ManagedHooksRequirementsToml,
L258:     requirement_source: Option<&RequirementSource>,
L259: ) -> AbsolutePathBuf {
L260:     if let Some(source_path) = managed_hooks.managed_dir_for_current_platform()
L261:         && source_path.is_absolute()
L262:         && let Ok(source_path) = AbsolutePathBuf::from_absolute_path(source_path)
L263:     {
L264:         return source_path;
L265:     }
L266: 
L267:     fallback_managed_hooks_source_path(requirement_source)
L268: }
L269: fn fallback_managed_hooks_source_path(
L270:     requirement_source: Option<&RequirementSource>,
L271: ) -> AbsolutePathBuf {
L272:     match requirement_source {
L273:         Some(RequirementSource::SystemRequirementsToml { file })
L274:         | Some(RequirementSource::LegacyManagedConfigTomlFromFile { file }) => file.clone(),
L275:         Some(RequirementSource::MdmManagedPreferences { domain, key }) => {
L276:             synthetic_layer_path(&format!("<mdm:{domain}:{key}>/requirements.toml"))
L277:         }
L278:         Some(RequirementSource::Composite { .. }) => {
L279:             synthetic_layer_path("<requirements-composition>/requirements.toml")
L280:         }
L281:         Some(RequirementSource::EnterpriseManaged { id, name }) => {
L282:             let name = escape_xml_text(name);
L283:             let id = escape_xml_text(id);
L284:             synthetic_layer_path(&format!(
L285:                 "<enterprise-managed:{name}:{id}>/requirements.toml"
L286:             ))
L287:         }
L288:         Some(RequirementSource::LegacyManagedConfigTomlFromMdm) => {
L289:             synthetic_layer_path("<legacy-managed-config.toml-mdm>/managed_config.toml")
L290:         }
L291:         Some(RequirementSource::Unknown) | None => {
L292:             synthetic_layer_path("<managed-requirements>/requirements.toml")
L293:         }
L294:     }
L295: }
L296: fn load_hooks_json(
L297:     config_folder: Option<&Path>,
L298:     warnings: &mut Vec<String>,
L299: ) -> Option<(AbsolutePathBuf, HookEventsToml)> {
L300:     let source_path = config_folder?.join("hooks.json");
L301:     if !source_path.as_path().is_file() {
L302:         return None;
L303:     }
L304:     let contents = match fs::read_to_string(source_path.as_path()) {
L305:         Ok(contents) => contents,
L306:         Err(err) => {
L307:             warnings.push(format!(
L308:                 "failed to read hooks config {}: {err}",
L309:                 source_path.display()
L310:             ));
L311:             return None;
L312:         }
L313:     };
L314:     let parsed: HooksFile = match serde_json::from_str(&contents) {
L315:         Ok(parsed) => parsed,
L316:         Err(err) => {
L317:             warnings.push(format!(
L318:                 "failed to parse hooks config {}: {err}",
L319:                 source_path.display()
L320:             ));
L321:             return None;
L322:         }
L323:     };
L324:     let source_path = AbsolutePathBuf::from_absolute_path(&source_path)
L325:         .inspect_err(|err| {
L326:             warnings.push(format!(
L327:                 "failed to normalize hooks config path {}: {err}",
L328:                 source_path.display()
L329:             ));
L330:         })
L331:         .ok()?;
L332: 
L333:     (!parsed.hooks.is_empty()).then_some((source_path, parsed.hooks))
L334: }
L335: fn load_toml_hooks_from_layer(
L336:     layer: &ConfigLayerEntry,
L337:     warnings: &mut Vec<String>,
L338: ) -> Option<(AbsolutePathBuf, HookEventsToml)> {
L339:     let source_path = config_toml_source_path(layer);
L340:     let hook_value = layer.config.get("hooks")?.clone();
L341:     let parsed = match HookEventsToml::deserialize(hook_value) {
L342:         Ok(parsed) => parsed,
L343:         Err(err) => {
L344:             warnings.push(format!(
L345:                 "failed to parse TOML hooks in {}: {err}",
L346:                 source_path.display()
L347:             ));
L348:             return None;
L349:         }
L350:     };
L351:     (!parsed.is_empty()).then_some((source_path, parsed))
L352: }
L353: fn config_toml_source_path(layer: &ConfigLayerEntry) -> AbsolutePathBuf {
L354:     match &layer.name {
L355:         ConfigLayerSource::System { file }
L356:         | ConfigLayerSource::User { file, .. }
L357:         | ConfigLayerSource::LegacyManagedConfigTomlFromFile { file } => file.clone(),
L358:         ConfigLayerSource::Project { dot_codex_folder } => layer
L359:             .hooks_config_folder()
L360:             .unwrap_or_else(|| dot_codex_folder.clone())
L361:             .join(CONFIG_TOML_FILE),
L362:         ConfigLayerSource::Mdm { domain, key } => {
L363:             synthetic_layer_path(&format!("<mdm:{domain}:{key}>/{CONFIG_TOML_FILE}"))
L364:         }
L365:         ConfigLayerSource::EnterpriseManaged { id, name } => synthetic_layer_path(&format!(
L366:             "<enterprise-managed:{name}:{id}>/{CONFIG_TOML_FILE}"
L367:         )),
L368:         ConfigLayerSource::LegacyManagedConfigTomlFromMdm => {
L369:             synthetic_layer_path("<legacy-managed-config.toml-mdm>/managed_config.toml")
L370:         }
L371:         ConfigLayerSource::SessionFlags => synthetic_layer_path("<session-flags>/config.toml"),
L372:     }
L373: }
L374: fn synthetic_layer_path(path: &str) -> AbsolutePathBuf {
L375:     #[cfg(windows)]
L376:     {
L377:         AbsolutePathBuf::resolve_path_against_base(path, r"C:\")
L378:     }
L379: 
L380:     #[cfg(not(windows))]
L381:     {
L382:         AbsolutePathBuf::resolve_path_against_base(path, "/")
L383:     }
L384: }
L385: fn escape_xml_text(value: &str) -> String {
L386:     let mut escaped = String::with_capacity(value.len());
L387:     for ch in value.chars() {
L388:         match ch {
L389:             '&' => escaped.push_str("&amp;"),
L390:             '<' => escaped.push_str("&lt;"),
L391:             '>' => escaped.push_str("&gt;"),
L392:             '"' => escaped.push_str("&quot;"),
L393:             '\'' => escaped.push_str("&apos;"),
L394:             _ => escaped.push(ch),
L395:         }
L396:     }
L397:     escaped
L398: }
L399: fn append_hook_events(
L400:     handlers: &mut Vec<ConfiguredHandler>,
L401:     hook_entries: &mut Vec<HookListEntry>,
L402:     warnings: &mut Vec<String>,
L403:     display_order: &mut i64,
L404:     source: HookHandlerSource<'_>,
L405:     hook_events: HookEventsToml,
L406:     policy: HookDiscoveryPolicy,
L407: ) {
L408:     if !policy.allows(&source) {
L409:         return;
L410:     }
L411:     for (event_name, groups) in hook_events.into_matcher_groups() {
L412:         append_matcher_groups(
L413:             handlers,
L414:             hook_entries,
L415:             warnings,
L416:             display_order,
L417:             &source,
L418:             event_name,
L419:             groups,
L420:         );
L421:     }
L422: }
L423: fn append_matcher_groups(
L424:     handlers: &mut Vec<ConfiguredHandler>,
L425:     hook_entries: &mut Vec<HookListEntry>,
L426:     warnings: &mut Vec<String>,
L427:     display_order: &mut i64,
L428:     source: &HookHandlerSource<'_>,
L429:     event_name: codex_protocol::protocol::HookEventName,
L430:     groups: Vec<MatcherGroup>,
L431: ) {
L432:     for (group_index, group) in groups.into_iter().enumerate() {
L433:         let matcher = matcher_pattern_for_event(event_name, group.matcher.as_deref());
L434:         if let Some(matcher) = matcher
L435:             && let Err(err) = validate_matcher_pattern(matcher)
L436:         {
L437:             warnings.push(format!(
L438:                 "invalid matcher {matcher:?} in {}: {err}",
L439:                 source.path.display()
L440:             ));
L441:             continue;
L442:         }
L443:         for (handler_index, handler) in group.hooks.iter().cloned().enumerate() {
L444:             let normalized = match handler {
L445:                 HookHandlerConfig::Command {
L446:                     command,
L447:                     command_windows,
L448:                     timeout_sec,
L449:                     r#async,
L450:                     status_message,
L451:                     additional_context_limit,
L452:                 } => {
L453:                     let command = if cfg!(windows) {
L454:                         command_windows.unwrap_or(command)
L455:                     } else {
L456:                         command
L457:                     };
L458:                     if command.trim().is_empty() {
L459:                         warnings.push(format!(
L460:                             "skipping empty hook command in {}",
L461:                             source.path.display()
L462:                         ));
L463:                         continue;
L464:                     }
L465:                     let timeout_sec = normalize_command_hook(
L466:                         event_name,
L467:                         timeout_sec,
L468:                         source.path.as_path(),
L469:                         warnings,
L470:                     );
L471:                     let runs_async = r#async
L472:                         && event_name != codex_protocol::protocol::HookEventName::SessionEnd;
L473:                     if r#async && !runs_async {
L474:                         warnings.push(format!(
L475:                             "running async SessionEnd hook synchronously in {}",
L476:                             source.path.display()
L477:                         ));
L478:                     }
L479:                     let additional_context_limit = if matches!(
L480:                         event_name,
L481:                         codex_protocol::protocol::HookEventName::PreToolUse
L482:                             | codex_protocol::protocol::HookEventName::PostToolUse
L483:                             | codex_protocol::protocol::HookEventName::SessionStart
L484:                             | codex_protocol::protocol::HookEventName::UserPromptSubmit
L485:                             | codex_protocol::protocol::HookEventName::SubagentStart
L486:                     ) {
L487:                         additional_context_limit
L488:                     } else {
L489:                         if additional_context_limit.is_some() {
L490:                             warnings.push(format!(
L491:                                 "ignoring additionalContextLimit for {event_name:?} hook in {}: this event cannot emit additionalContext",
L492:                                 source.path.display()
L493:                             ));
L494:                         }
L495:                         None
L496:                     };
L497:                     let normalized_additional_context_limit = additional_context_limit
L498:                         .filter(|limit| *limit != DEFAULT_HOOK_OUTPUT_TOKEN_LIMIT);
L499:                     let config = HookHandlerConfig::Command {
L500:                         command: command.clone(),
L501:                         command_windows: None,
L502:                         timeout_sec: Some(timeout_sec),
L503:                         r#async,
L504:                         status_message: status_message.clone(),
L505:                         additional_context_limit: normalized_additional_context_limit,
L506:                     };
L507:                     let command = source.env.iter().fold(command, |command, (key, value)| {
L508:                         command.replace(&format!("${{{key}}}"), value)
L509:                     });
L510:                     NormalizedHandler {
L511:                         config,
L512:                         kind: ConfiguredHandlerKind::Command {
L513:                             command,
L514:                             env: source.env.clone(),
L515:                             r#async: runs_async,
L516:                         },
L517:                         timeout_sec,
L518:                         status_message,
L519:                         additional_context_limit,
L520:                     }
L521:                 }
L522:                 HookHandlerConfig::McpTool { .. } => {
L523:                     warnings.push(format!(
L524:                         "skipping MCP tool hook in {}: MCP tool hooks are not supported yet",
L525:                         source.path.display()
L526:                     ));
L527:                     continue;
L528:                 }
L529:                 HookHandlerConfig::Prompt {} => {
L530:                     warnings.push(format!(
L531:                         "skipping prompt hook in {}: prompt hooks are not supported yet",
L532:                         source.path.display()
L533:                     ));
L534:                     continue;
L535:                 }
L536:                 HookHandlerConfig::Agent {} => {
L537:                     warnings.push(format!(
L538:                         "skipping agent hook in {}: agent hooks are not supported yet",
L539:                         source.path.display()
L540:                     ));
L541:                     continue;
L542:                 }
L543:             };
L544:             let NormalizedHandler {
L545:                 config,
L546:                 kind,
L547:                 timeout_sec,
L548:                 status_message,
L549:                 additional_context_limit,
L550:             } = normalized;
L551:             let current_hash = hook_hash(event_name, matcher, &group, config);
L552:             let key = crate::hook_key(&source.key_source, event_name, group_index, handler_index);
L553:             let state = source.hook_states.get(&key);
L554:             let enabled = hook_enabled(source.is_managed, state);
L555:             let trusted_hash = hook_trusted_hash(source.is_managed, state);
L556:             let trust_status = hook_trust_status(source.is_managed, &current_hash, trusted_hash);
L557:             let ConfiguredHandlerKind::Command { command, .. } = &kind;
L558:             let execution_mode =
L559:                 if matches!(kind, ConfiguredHandlerKind::Command { r#async: true, .. }) {
L560:                     HookExecutionMode::Async
L561:                 } else {
L562:                     HookExecutionMode::Sync
L563:                 };
L564:             hook_entries.push(HookListEntry {
L565:                 key,
L566:                 event_name,
L567:                 handler_type: HookHandlerType::Command,
L568:                 matcher: matcher.map(ToOwned::to_owned),
L569:                 command: Some(command.clone()),
L570:                 timeout_sec,
L571:                 status_message: status_message.clone(),
L572:                 additional_context_limit,
L573:                 source_path: source.path.clone(),
L574:                 source: source.source,
L575:                 plugin_id: source.plugin_id.clone(),
L576:                 display_order: *display_order,
L577:                 enabled,
L578:                 is_managed: source.is_managed,
L579:                 current_hash,
L580:                 trust_status,
L581:                 execution_mode,
L582:             });
L583:             if enabled
L584:                 && (source.bypass_hook_trust
L585:                     || matches!(
L586:                         trust_status,
L587:                         HookTrustStatus::Managed | HookTrustStatus::Trusted
L588:                     ))
L589:             {
L590:                 handlers.push(ConfiguredHandler {
L591:                     event_name,
L592:                     matcher: matcher.map(ToOwned::to_owned),
L593:                     timeout_sec,
L594:                     status_message,
L595:                     additional_context_limit: AdditionalContextLimit::from_config(
L596:                         additional_context_limit,
L597:                     ),
L598:                     source_path: source.path.clone(),
L599:                     source: source.source,
L600:                     display_order: *display_order,
L601:                     kind,
L602:                 });
L603:             }
L604:             *display_order += 1;
L605:         }
L606:     }
L607: }
L608: /// Normalizes command-hook timeouts. SessionEnd defaults to one second and is capped at three
L609: /// seconds; all other command hooks keep the standard ten-minute default.
L610: fn normalize_command_hook(
L611:     event_name: codex_protocol::protocol::HookEventName,
L612:     timeout_sec: Option<u64>,
L613:     source_path: &Path,
L614:     warnings: &mut Vec<String>,
L615: ) -> u64 {
L616:     if event_name != codex_protocol::protocol::HookEventName::SessionEnd {
L617:         return timeout_sec.unwrap_or(600).max(1);
L618:     }
L619:     let max_timeout_sec = SESSION_END_MAX_TIMEOUT_SEC;
L620:     if timeout_sec.is_some_and(|timeout_sec| timeout_sec > max_timeout_sec) {
L621:         warnings.push(format!(
L622:             "clamping SessionEnd hook timeout to {max_timeout_sec}s in {}",
L623:             source_path.display()
L624:         ));
L625:     }
L626:     timeout_sec
L627:         .unwrap_or(SESSION_END_DEFAULT_TIMEOUT_SEC)
L628:         .clamp(1, max_timeout_sec)
L629: }
L630: /// Hash a normalized, config-derived identity instead of source text so equivalent
L631: /// hooks from config TOML and hooks.json converge on the same trust identity.
L632: #[derive(Serialize)]
L633: struct NormalizedHookIdentity {
L634:     event_name: &'static str,
L635:     #[serde(flatten)]
L636:     group: MatcherGroup,
L637: }
L638: fn hook_hash(
L639:     event_name: codex_protocol::protocol::HookEventName,
L640:     matcher: Option<&str>,
L641:     group: &MatcherGroup,
L642:     normalized_handler: HookHandlerConfig,
L643: ) -> String {
L644:     let mut group = group.clone();
L645:     group.matcher = matcher.map(ToOwned::to_owned);
L646:     group.hooks = vec![normalized_handler];
L647:     let identity = NormalizedHookIdentity {
L648:         event_name: crate::hook_event_key_label(event_name),
L649:         group,
L650:     };
L651:     let Ok(value) = TomlValue::try_from(identity) else {
L652:         unreachable!("normalized hook identity should serialize to TOML");
L653:     };
L654:     version_for_toml(&value)
L655: }
L656: fn hook_trust_status(
L657:     is_managed: bool,
L658:     current_hash: &str,
L659:     trusted_hash: Option<&str>,
L660: ) -> HookTrustStatus {
L661:     if is_managed {
L662:         HookTrustStatus::Managed
L663:     } else {
L664:         match trusted_hash {
L665:             Some(trusted_hash) if trusted_hash == current_hash => HookTrustStatus::Trusted,
L666:             Some(_) => HookTrustStatus::Modified,
L667:             None => HookTrustStatus::Untrusted,
L668:         }
L669:     }
L670: }
L671: fn hook_enabled(is_managed: bool, state: Option<&HookStateToml>) -> bool {
L672:     is_managed || state.and_then(|state| state.enabled) != Some(false)
L673: }
L674: 
L675: fn hook_trusted_hash(is_managed: bool, state: Option<&HookStateToml>) -> Option<&str> {
L676:     (!is_managed)
L677:         .then(|| state.and_then(|state| state.trusted_hash.as_deref()))
L678:         .flatten()
L679: }
L680: fn hook_metadata_for_config_layer_source(source: &ConfigLayerSource) -> (HookSource, bool) {
L681:     match source {
L682:         ConfigLayerSource::System { .. } => (HookSource::System, true),
